**M7.B — Pre-flight orphan IPC scan:**
```typescript
// src/core/orphan-cleaner.ts içine ekle
export async function cleanOrphanIpcDirs(root: string, currentJobId: string): Promise<number> {
  const deckentDir = path.join(root, '.deckent');
  const entries = await fs.readdir(deckentDir).catch(() => []);
  const ipcPattern = /^sprint-\d+-ipc$/;
  let cleaned = 0;
  for (const entry of entries) {
    if (!ipcPattern.test(entry)) continue;
    const jobIdMatch = entry.match(/sprint-(\d+)-ipc/);
    if (!jobIdMatch) continue;
    const jobId = jobIdMatch[1];
    if (jobId === currentJobId) continue;  // protect current
    await fs.rm(path.join(deckentDir, entry), { recursive: true, force: true });
    cleaned++;
  }
  return cleaned;
}
```

`preflightOrphanCleanup()` çağrı zincirine ekle.

